import { apiRequest, apiRequestNullable } from "./api";
export { AUTH_PASSWORD_MAX_LENGTH, AUTH_PASSWORD_MIN_LENGTH, AUTH_USERNAME_MAX_LENGTH, AUTH_USERNAME_MIN_LENGTH, } from "../utils/input-validation";
function emitAuthChanged() {
    window.dispatchEvent(new Event("auth-changed"));
    localStorage.setItem("auth-changed", Date.now().toString());
}
export async function login(payload) {
    const user = await apiRequest("/auth/login", {
        method: "POST",
        body: JSON.stringify(payload),
    });
    emitAuthChanged();
    return user;
}
export async function register(payload) {
    const user = await apiRequest("/auth/register", {
        method: "POST",
        body: JSON.stringify(payload),
    });
    emitAuthChanged();
    return user;
}
export async function loginAsGuest(payload) {
    const user = await apiRequest("/auth/guest", {
        method: "POST",
        body: JSON.stringify(payload),
    });
    emitAuthChanged();
    return user;
}
export function getSession() {
    return apiRequestNullable("/auth/session");
}
export async function logout() {
    const result = await apiRequest("/auth/logout", {
        method: "POST",
        body: JSON.stringify({}),
    });
    emitAuthChanged();
    return result;
}
