import { apiRequest } from "./api";
function emitAuthChanged() {
    window.dispatchEvent(new Event("auth-changed"));
}
export function getUserById(userId) {
    return apiRequest(`/users/${userId}`);
}
export function getMyFriendOverview() {
    return apiRequest("/users/me/friends");
}
export function sendFriendRequest(username) {
    return apiRequest("/users/me/friends", {
        method: "POST",
        body: JSON.stringify({ username }),
    });
}
export function respondToFriendRequest(requestId, action) {
    return apiRequest(`/users/me/friends/requests/${requestId}`, {
        method: "PATCH",
        body: JSON.stringify({ action }),
    });
}
export function removeFriend(friendId) {
    return apiRequest(`/users/me/friends/${friendId}`, {
        method: "DELETE",
    });
}
export function getConversationSummaries() {
    return apiRequest("/users/me/friends/conversations");
}
export function getPrivateConversation(friendId) {
    return apiRequest(`/users/me/friends/messages/${friendId}`);
}
export function sendPrivateMessage(friendId, content) {
    return apiRequest(`/users/me/friends/messages/${friendId}`, {
        method: "POST",
        body: JSON.stringify({ content }),
    });
}
export function updateMyAvatar(avatarDataUrl) {
    return apiRequest("/users/me/avatar", {
        method: "PATCH",
        body: JSON.stringify({ avatarDataUrl }),
    }).then((user) => {
        emitAuthChanged();
        return user;
    });
}
export function updateMyProfile(payload) {
    return apiRequest("/users/me/profile", {
        method: "PATCH",
        body: JSON.stringify(payload),
    }).then((user) => {
        emitAuthChanged();
        return user;
    });
}
