import { apiRequest } from "./api";
export function getQuizLeaderboard(quizId, limit = 10) {
    return apiRequest(`/scores/quizzes/${quizId}/leaderboard?limit=${limit}`);
}
export function getWinsLeaderboard(limit = 10) {
    return apiRequest(`/scores/leaderboard/wins?limit=${limit}`);
}
export function getUserWinsRank(userId) {
    return apiRequest(`/scores/users/${userId}/wins-rank`);
}
